,21.01,24.62,28.60],[16.56,18.31,21.03,24.64,28.63],[16.57,18.33,21.05,24.67,28.65],[16.58,18.34,21.07,24.69,28.67],[16.59,18.36,21.09,24.72,28.70],[16.60,18.37,21.11,24.74,28.72],[16.61,18.38,21.12,24.76,28.74],[16.61,18.39,21.14,24.78,28.76],[16.62,18.40,21.16,24.80,28.77],[16.63,18.41,21.17,24.82,28.79],[16.63,18.42,21.19,24.84,28.81],[16.64,18.44,21.20,24.86,28.82],[16.64,18.44,21.22,24.87,28.84],[16.65,18.45,21.23,24.89,28.85],[16.66,18.46,21.25,24.91,28.87],[16.66,18.47,21.26,24.93,28.88],[16.67,18.48,21.28,24.95,28.90],[16.67,18.50,21.29,24.96,28.91],[16.68,18.51,21.31,24.98,28.93],[16.69,18.52,21.32,25.00,28.95],[16.69,18.53,21.34,25.02,28.96],[16.70,18.54,21.36,25.04,28.98],[16.71,18.56,21.38,25.07,29.00],[16.72,18.57,21.40,25.09,29.02],[16.73,18.59,21.42,25.12,29.05],[16.74,18.61,21.44,25.15,29.07],[16.76,18.63,21.47,25.18,29.10]]}'::jsonb;
  months int;
  row_ jsonb;
  p3 numeric; p15 numeric; p85 numeric; p97 numeric;
BEGIN
  IF imc IS NULL THEN RETURN NULL; END IF;
  
  -- Se age_months for informado, utiliza diretamente; caso contrário, estima por age
  IF age_months IS NOT NULL THEN
    IF age_months < 60 THEN RETURN NULL; END IF;
    IF age_months >= 240 THEN
      IF imc < 16 THEN RETURN 'Muito Fraco'; END IF;
      IF imc < 18.5 THEN RETURN 'Fraco'; END IF;
      IF imc < 25 THEN RETURN 'Excelente'; END IF;
      IF imc < 30 THEN RETURN 'Razoável'; END IF;
      RETURN 'Muito Fraco';
    END IF;
    months := LEAST(228, GREATEST(60, age_months));
  ELSE
    IF age IS NULL THEN RETURN NULL; END IF;
    IF age >= 20 THEN
      IF imc < 16 THEN RETURN 'Muito Fraco'; END IF;
      IF imc < 18.5 THEN RETURN 'Fraco'; END IF;
      IF imc < 25 THEN RETURN 'Excelente'; END IF;
      IF imc < 30 THEN RETURN 'Razoável'; END IF;
      RETURN 'Muito Fraco';
    END IF;
    IF age < 5 THEN RETURN NULL; END IF;
    months := LEAST(228, GREATEST(60, age * 12 + 6));
  END IF;

  row_ := ref -> (CASE WHEN sex = 'male' THEN 'male' ELSE 'female' END) -> (months - 60);
  p3  := (row_ ->> 0)::numeric;
  p15 := (row_ ->> 1)::numeric;
  p85 := (row_ ->> 3)::numeric;
  p97 := (row_ ->> 4)::numeric;
  IF imc < p3  THEN RETURN 'Fraco';       END IF;  -- magreza
  IF imc < p15 THEN RETURN 'Bom';         END IF;  -- eutrofia (limite inferior)
  IF imc <= p85 THEN RETURN 'Excelente';  END IF;  -- eutrofia
  IF imc <= p97 THEN RETURN 'Razoável';   END IF;  -- sobrepeso
  RETURN 'Muito Fraco';                            -- obesidade
END $$;

ALTER FUNCTION public._imc_zone(numeric, integer, text, integer) SET search_path = public;

-- 3. Atualizar compute_eval_classifications para receber _age_months opcional
CREATE OR REPLACE FUNCTION public.compute_eval_classifications(
  _sex text, _age int,
  _weight numeric, _height numeric, _waist numeric,
  _imc numeric, _rce numeric,
  _flex numeric, _abdo numeric, _jump numeric, _mball numeric,
  _square numeric, _sprint numeric, _run6 numeric,
  _age_months int DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  imc numeric := COALESCE(_imc, CASE WHEN _weight>0 AND _height>0 THEN _weight/((_height/100)*(_height/100)) END);
  rce numeric := COALESCE(_rce, CASE WHEN _waist>0 AND _height>0 THEN _waist/_height END);
  out jsonb := '{}'::jsonb;
  z text;
BEGIN
  IF _sex IS NULL OR (_age IS NULL AND _age_months IS NULL) THEN RETURN out; END IF;
  z := public._imc_zone(imc, _age, _sex, _age_months); IF z IS NOT NULL THEN out := out || jsonb_build_object('imc', z); END IF;
  z := public._rce_zone(rce);                          IF z IS NOT NULL THEN out := out || jsonb_build_object('rce', z); END IF;
  z := public._classify_higher(_flex,  public._cuts('flex',_sex,_age));   IF z IS NOT NULL THEN out := out || jsonb_build_object('flex', z); END IF;
  z := public._classify_higher(_abdo,  public._cuts('abdo',_sex,_age));   IF z IS NOT NULL THEN out := out || jsonb_build_object('abdo', z); END IF;
  z := public._classify_higher(_jump,  public._cuts('jump',_sex,_age));   IF z IS NOT NULL THEN out := out || jsonb_build_object('jump', z); END IF;
  z := public._classify_higher(_mball, public._cuts('mball',_sex,_age));  IF z IS NOT NULL THEN out := out || jsonb_build_object('mball', z); END IF;
  z := public._classify_lower(_square, public._cuts('square',_sex,_age)); IF z IS NOT NULL THEN out := out || jsonb_build_object('square', z); END IF;
  z := public._classify_lower(_sprint, public._cuts('sprint',_sex,_age)); IF z IS NOT NULL THEN out := out || jsonb_build_object('sprint', z); END IF;
  z := public._classify_higher(_run6,  public._cuts('run6',_sex,_age));   IF z IS NOT NULL THEN out := out || jsonb_build_object('run6', z); END IF;
  RETURN out;
END $$;

ALTER FUNCTION public.compute_eval_classifications(text, integer, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer) SET search_path = public;

-- 4. Atualizar evaluations_fill_classifications para calcular age_years e age_months via calendário
CREATE OR REPLACE FUNCTION public.evaluations_fill_classifications()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  _sex text;
  _bd date;
  _age int;
  _age_m int;
BEGIN
  SELECT sex::text, birth_date INTO _sex, _bd FROM public.students WHERE id = NEW.student_id;
  
  -- Cálculo de calendário civil completo
  _age := COALESCE(NEW.age_years, CASE WHEN _bd IS NOT NULL THEN EXTRACT(year FROM age(NEW.evaluated_at::date, _bd))::int END);
  _age_m := COALESCE(NEW.age_months, CASE WHEN _bd IS NOT NULL THEN (EXTRACT(year FROM age(NEW.evaluated_at::date, _bd))::int * 12 + EXTRACT(month FROM age(NEW.evaluated_at::date, _bd))::int) END);
  
  NEW.age_years := _age;
  NEW.age_months := _age_m;
  
  IF NEW.imc IS NULL AND NEW.weight_kg>0 AND NEW.height_cm>0 THEN
    NEW.imc := round((NEW.weight_kg/((NEW.height_cm/100)*(NEW.height_cm/100)))::numeric, 2);
  END IF;
  IF NEW.rce IS NULL AND NEW.waist_cm>0 AND NEW.height_cm>0 THEN
    NEW.rce := round((NEW.waist_cm/NEW.height_cm)::numeric, 3);
  END IF;
  
  NEW.classifications := public.compute_eval_classifications(
    _sex, _age, NEW.weight_kg, NEW.height_cm, NEW.waist_cm, NEW.imc, NEW.rce,
    NEW.sit_and_reach_cm, NEW.abdominal_reps, NEW.horizontal_jump_cm, NEW.medicine_ball_m,
    NEW.square_test_s, NEW.sprint_20m_s, NEW.run_6min_m,
    _age_m
  );
  RETURN NEW;
END $$;
